scene.sky_texture(35.0, 12.0, 0.1)
scene.checker_ground(7.0,4.0)
scene.fit_camera(46.0)
scene.render_settings(12,35,True)
scene.render_png("blender/sky-texture.png", 64, 640, 480)
lmb_bpy.done()
